INSERT INTO public.listing_transaction_terms (listing_id, term_code, label_th, label_en, value_th, value_en, payer_code, sort_order) VALUES (property_listing_id, 'title_and_boundary', 'โฉนดตราจองและแนวเขต', 'Tra Chong title and boundaries', 'โฉนดตราจอง 1491 ไม่มีระวางรูปแผนที่ตามข้อมูล SAM ต้องตรวจตำแหน่งและแนวเขตจริง', 'Tra Chong 1491; SAM reports no cadastral sheet; verify actual location and boundaries', 'unspecified', 20) ;
INSERT INTO public.listing_transaction_terms (listing_id, term_code, label_th, label_en, value_th, value_en, payer_code, sort_order) VALUES (property_listing_id, 'royal_reserved_area', 'เขตทรงสงวนและการอนุญาต', 'Royal reserved area and permission', 'SAM ระบุว่าต้องขออนุญาตจากกองทัพเรือ และอาจเพิกถอนการอนุญาตรวมถึงเอกสารสิทธิหากผิดเงื่อนไข โดยต้นทางระบุไม่มีสิทธิโต้แย้งหรือเรียกค่าเสียหาย ต้องตรวจหลักฐานแปลงนี้', 'SAM reports Navy permission requirements and possible permission/title revocation for unmet conditions, with no contest or compensation; verify plot-specific records', 'unspecified', 30) ;
INSERT INTO public.listing_transaction_terms (listing_id, term_code, label_th, label_en, value_th, value_en, payer_code, sort_order) VALUES (property_listing_id, 'northern_land_use', 'การใช้พื้นที่ด้านเหนือ', 'Northern land use', 'SAM ระบุข้างเคียงใช้พื้นที่ด้านเหนือบางส่วน อาจเป็นการก่อสร้างรุกล้ำหรือใช้ประโยชน์ ต้องตรวจสอบ', 'SAM reports neighbouring use of part of the northern land, potentially involving encroachment; investigate', 'unspecified', 40) ;
INSERT INTO public.listing_transaction_terms (listing_id, term_code, label_th, label_en, value_th, value_en, payer_code, sort_order) VALUES (property_listing_id, 'current_inspection', 'ตรวจสภาพปัจจุบัน', 'Current inspection', 'ภาพวันที่ 11 กรกฎาคม 2567 ไม่ระบุพื้นที่ใช้สอย จำนวนห้องหรือผู้ครอบครอง', 'Photos 11 July 2024; usable area, room counts and occupancy not published', 'unspecified', 50) ;
