INSERT INTO public.listing_sources (listing_id, source_type, publisher_name, source_url, reference_code, captured_at, notes) VALUES (property_listing_id, 'editorial_import', 'บริษัท บริหารสินทรัพย์สุขุมวิท จำกัด (SAM)', 'https://www.sam.or.th/site/npa/detail.php?id=12905&keyref=6007684', '8Z5730', now(), 'Official source captured 2026-09-11. THB 7,478,000; 60 sq.wah; three interconnected two-storey shophouses. Tra Chong 1491, reserved-area permission/revocation and no contest/compensation wording, no cadastral sheet and neighbouring northern use/possible encroachment are disclosed as SAM-reported information. No independent legal conclusion or plot permission confirmation. 23 source image URLs reduced to 22 byte-unique images; duplicate cover omitted. Photos dated 2024-07-11. Navigation/map agree. All-status code/page/title/address/nearby duplicate search found no matches.') ;
